/**
 * How Nakatsu round fan (`nakatsu-uchiwa`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/nakatsu-uchiwa";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Rule a central handle and strike a matching face on either side. Leave a narrow white seam inside each rim. Place five pines from top to bottom on each face and rule the strokes on their crowns.","ja":"中央の柄を引き、左右同じ地紙を弧で打ちます。ふちの内側には細い白筋を残します。各面に松を上から五つ置き、松葉の筋を引きます。"};

export default construction;
export { construction, description };
